def eprint(s=""):
    print(s, file=sys.stderr)

def os_error_text(exc):
    if isinstance(exc, OSError):
        msg = exc.strerror or str(exc)
        num = exc.errno
        if num is not None:
            return f"{msg} (os error {num})"
    return str(exc)

# ---------- CLI parsing ----------

def usage_general(name):
    return f"Usage: {name} [OPTIONS] [[SOURCE] OUTPUT]..."

def unexpected_arg(arg, name):
    return (f"error: unexpected argument '{arg}' found\n\n"
            f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"
            f"{usage_general(name)}\n\n"
            f"For more information, try '--help'.")

def missing_value(opt, value_name, possible=False):
    s = f"error: a value is required for '{opt} <{value_name}>' but none was supplied"
    if possible:
        s += "\n  [possible values: asc, desc]"
    s += "\n\nFor more information, try '--help'."
    return s

def invalid_sort(val):
    return (f"error: invalid value '{val}' for '--sort <ORDER>'\n"
            f"  [possible values: asc, desc]\n\n"
