            f"For more information, try '--help'.")

def parse_uint_value(val, optname):
    if val == "" or not val.isdigit():
        raise AppError(invalid_uint(val, optname), 2)
    try:
        return int(val)
    except Exception:
        raise AppError(invalid_uint(val, optname), 2)

def parse_args(argv):
    name = prog_base(argv[0])
    opts = Options()
    args = argv[1:]
    i = 0
    end_opts = False

    def need_next(current, value_name, possible=False):
        nonlocal i
        if i + 1 >= len(args):
            raise AppError(missing_value(current, value_name, possible), 2)
        nxt = args[i+1]
        if nxt.startswith('-'):
            # clap reports negative-looking values as unexpected arguments unless passed with '='
            raise AppError(unexpected_arg(nxt, name), 2)
        i += 1
        return nxt

    long_value_names = {
        'dir': ('PATH', False), 'depth': ('DEPTH', False), 'generate': ('PATH', False),
        'map': ('PATH', False), 'from-file': ('PATH', False), 'max-depth': ('DEPTH', False),
        'regex': ('PATTERN', False), 'sort': ('ORDER', True)
    }

    while i < len(args):
