                has_eq = False
            if key == 'no-extension':
                opts.no_extension = True
            elif key == 'help':
                sys.stdout.write(long_help(name)); raise CliExit(0)
            elif key == 'mkdir':
                opts.mkdir = True
            elif key == 'quiet':
                opts.quiet = True
            elif key in ('test', 'dry-run'):
