                if c == 'E':
                    opts.no_extension = True; j += 1; continue
                if c == 'k':
                    opts.mkdir = True; j += 1; continue
                if c == 'q':
                    opts.quiet = True; j += 1; continue
                if c == 't':
                    opts.test = True; j += 1; continue
                if c == 'w':
