# ---------- natural sorting and traversal ----------

def is_ascii_digit(ch):
    return '0' <= ch <= '9'

def natural_cmp(a, b):
    i = j = 0
    la, lb = len(a), len(b)
    while i < la and j < lb:
        ca, cb = a[i], b[j]
        if is_ascii_digit(ca) and is_ascii_digit(cb):
            ia, jb = i, j
            while i < la and is_ascii_digit(a[i]):
                i += 1
            while j < lb and is_ascii_digit(b[j]):
                j += 1
            ra, rb = a[ia:i], b[jb:j]
            # Numeric comparison first, then the original digit run lexicographically.
            na = int(ra) if ra else 0
            nb = int(rb) if rb else 0
            if na != nb:
                return -1 if na < nb else 1
            if ra != rb:
                return -1 if ra < rb else 1
            continue
        if ca != cb:
            return -1 if ca < cb else 1
        i += 1
        j += 1
    if la == lb:
        return 0
    return -1 if la < lb else 1

def natural_sorted(seq, reverse=False):
    return sorted(seq, key=cmp_to_key(natural_cmp), reverse=reverse)

def immediate_entries():
    try:
        names = os.listdir('.')
    except OSError as e:
        raise AppError('error: ' + os_error_text(e), 1)
    return natural_sorted(names)

def rel_join(base, name):
    return name if base == '' else base + '/' + name

def walk_entries_exact(depth):
    if depth == 0:
        return ['']
    return walk_entries_range(depth, depth)

def walk_entries_range(min_depth, max_depth):
    # min_depth is normally 1 except the special max-depth 0 case.
    results = []
    def rec(rel, current_depth):
        # rel is current directory relative path, current_depth its component count (root = 0)
        if current_depth >= max_depth:
            return
        try:
            names = os.listdir(rel if rel else '.')
        except OSError:
            return
        for name in natural_sorted(names):
            child_rel = rel_join(rel, name)
            d = current_depth + 1
            if min_depth <= d <= max_depth:
                results.append(child_rel)
            # Descend only into real directories, not symlinked directories.
            try:
                if os.path.isdir(child_rel) and not os.path.islink(child_rel):
                    rec(child_rel, d)
            except OSError:
                pass
    rec('', 0)
    return natural_sorted(results)

def infer_depth_from_pattern(pattern):
    if pattern == '':
        return 1
    comps = [c for c in pattern.split('/') if c != '']
    return max(1, len(comps))

# ---------- extension and placeholders ----------

def rust_extension(path):
    # Rust Path::extension-like behavior for the final path component.
    base = path.rsplit('/', 1)[-1]
    if base == '' or base == '.' or base == '..':
        return None
    idx = base.rfind('.')
    if idx < 0:
        return None
    if idx == 0:
        return None
    return base[idx+1:]

class Formatter:
    def __init__(self, fmt):
        self.fmt = fmt
        self.tokens = []
        self._parse()

    def _parse_placeholder(self, content):
        if ':' in content:
            group, pad_s = content.split(':', 1)
            if pad_s == '':
                pad = None
            else:
                if not pad_s.isdigit():
                    raise AppError(f"error: [output-format] unable to parse padding of '{pad_s}'", 1)
                try:
                    pad = int(pad_s)
                except Exception:
                    raise AppError(f"error: [output-format] unable to parse padding of '{pad_s}'", 1)
        else:
            group, pad = content, None
        if group == '':
            g = None
        elif group.isdigit():
            g = int(group)
        else:
            g = group
        self.tokens.append(('ph', g, pad))

    def _parse(self):
        s = self.fmt
        i = 0
        lit = []
        while i < len(s):
            ch = s[i]
            if ch == '\\' and i + 1 < len(s) and s[i+1] in '{}':
                lit.append(s[i+1])
                i += 2
                continue
            if ch == '{':
                if lit:
                    self.tokens.append(('lit', ''.join(lit)))
                    lit = []
                i += 1
                content = []
                closed = False
                while i < len(s):
                    if s[i] == '\\' and i + 1 < len(s) and s[i+1] in '{}':
                        # Escaped braces inside a placeholder are treated as literal content.
                        content.append(s[i+1])
                        i += 2
                        continue
                    if s[i] == '}':
                        closed = True
                        i += 1
                        break
                    content.append(s[i])
                    i += 1
                if not closed:
                    raise AppError("error: [output-format] all opened placeholders must be closed by '}'", 1)
                self._parse_placeholder(''.join(content))
                continue
            if ch == '}':
                raise AppError("error: [output-format] an unopened placeholder could not be closed by '}'", 1)
            lit.append(ch)
            i += 1
        if lit:
            self.tokens.append(('lit', ''.join(lit)))

    def format(self, ctx):
        # ctx: {'groups': list, 'named': dict}
        groups = ctx.get('groups', [])
        named = ctx.get('named', {})
        auto = 1
        out = []
        for tok in self.tokens:
            if tok[0] == 'lit':
                out.append(tok[1])
            else:
                _, g, pad = tok
                if g is None:
                    idx = auto
                    auto += 1
                    val = groups[idx] if idx < len(groups) and groups[idx] is not None else ''
                elif isinstance(g, int):
                    val = groups[g] if g < len(groups) and groups[g] is not None else ''
                else:
                    v = named.get(g, '')
                    val = '' if v is None else v
                if pad is not None and val != '':
                    if re.fullmatch(r'[+-]?\d+', val):
                        try:
                            n = int(val)
                            if n >= 0:
                                val = str(n).zfill(pad)
                        except Exception:
                            pass
                out.append(val)
        return ''.join(out)

# ---------- regex ----------

def convert_rust_named_regex(pattern):
    # Python does not accept Rust's (?<name>...), but does accept (?P<name>...).
    return re.sub(r'\(\?<([A-Za-z_][A-Za-z0-9_]*)>', r'(?P<\1>', pattern)

def compile_regex(pattern):
    py_pat = convert_rust_named_regex(pattern)
    try:
        return re.compile(py_pat)
    except re.error as e:
        pos = getattr(e, 'pos', 0) or 0
        caret = ' ' * pos + '^'
        msg = str(e)
        if 'unterminated character set' in msg:
            msg2 = 'unclosed character class'
        elif 'missing ), unterminated subpattern' in msg:
            msg2 = 'unclosed group'
        else:
            # Python includes position details in str(e); trim the common suffix for readability.
            msg2 = msg
        raise AppError(f"error: regex parse error:\n    {pattern}\n    {caret}\nerror: {msg2}", 1)

# ---------- planning / collision ----------

def prepend_underscore(path):
    if '/' in path:
        d, b = path.rsplit('/', 1)
        return d + '/_' + b
    return '_' + path

def target_exists(path):
    try:
        return os.path.exists(path) or os.path.islink(path)
    except OSError:
        return False

def resolve_collision_initial(desired, inp, initial_set, overwrite):
    if overwrite:
        return desired
    out = desired
    while out != inp and out in initial_set:
        out = prepend_underscore(out)
    return out

def resolve_collision_current(desired, inp, overwrite):
    if overwrite:
        return desired
    out = desired
    while out != inp and target_exists(out):
        out = prepend_underscore(out)
    return out

