    s = set()
    # A conservative full walk of the working tree, including directories and symlinks.
    def rec(rel):
        try:
            names = os.listdir(rel if rel else '.')
        except OSError:
            return
        for name in names:
            child = rel_join(rel, name)
            s.add(child)
            try:
                if os.path.isdir(child) and not os.path.islink(child):
                    rec(child)
            except OSError:
                pass
    rec('')
    return s

def candidate_sort(opts, formatter):
    names = immediate_entries()
    if opts.sort == 'desc':
        names = list(reversed(names))
    out = []
    for idx, inp in enumerate(names, 1):
        groups = [inp, str(idx)]
        desired = formatter.format({'groups': groups, 'named': {}})
        if not opts.no_extension:
            ext = rust_extension(inp)
            if ext is not None:
                desired += '.' + ext
        out.append((inp, desired))
    return out

def candidate_regex(opts, formatter, cregex):
    if opts.max_depth is not None:
        if opts.max_depth == 0:
            entries = ['']
        else:
            entries = walk_entries_range(1, opts.max_depth)
    else:
        d = opts.depth if opts.depth is not None else infer_depth_from_pattern(opts.regex)
        entries = walk_entries_exact(d)
    out = []
    for inp in entries:
        m = cregex.search(inp)
        if not m:
            continue
        groups = []
        # Python returns the whole match plus explicit capture groups.
        for k in range(0, len(m.groups()) + 1):
            groups.append(m.group(k))
        named = m.groupdict()
        desired = formatter.format({'groups': groups, 'named': named})
        if not opts.no_extension:
            ext = rust_extension(inp)
            if ext is not None:
                desired += '.' + ext
        out.append((inp, desired))
    return out

def json_type_name(v, for_value=False):
    if isinstance(v, str): return 'string'
    if isinstance(v, bool): return f"boolean `{str(v).lower()}`" if not for_value else f"boolean `{str(v).lower()}`"
    if v is None: return 'null'
    if isinstance(v, int): return f"integer `{v}`"
    if isinstance(v, float): return f"floating point `{v}`"
    if isinstance(v, list): return 'sequence'
    if isinstance(v, dict): return 'map'
    return type(v).__name__

def load_map_pairs(path):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except OSError as e:
        raise AppError('error: ' + os_error_text(e), 1)
    try:
        data = json.loads(text, object_pairs_hook=OrderedDict)
    except json.JSONDecodeError as e:
        # serde_json's message for unquoted object keys is common and documented by observations.
        if text.lstrip().startswith('{'):
            raise AppError(f"error: key must be a string at line {e.lineno} column {e.colno}", 1)
        raise AppError(f"error: {e.msg} at line {e.lineno} column {e.colno}", 1)
    if not isinstance(data, OrderedDict):
        # serde_json columns for scalar top-level values point at the end; close enough for common cases.
        if isinstance(data, list):
            col = 0
        elif data is None:
            col = 4
        elif isinstance(data, bool):
            col = 4 if data else 5
        else:
            col = len(str(data))
        raise AppError(f"error: invalid type: {json_type_name(data)}, expected a map at line 1 column {col}", 1)
    pairs = []
    # Python has already ensured keys are strings for JSON objects.
    for k, v in data.items():
        if not isinstance(v, str):
            # Exact columns are not semantically important; approximate serde_json wording.
            raise AppError(f"error: invalid type: {json_type_name(v, True)}, expected a string at line 1 column 5", 1)
        pairs.append((k, v))
    return pairs

def candidate_map(opts):
    return load_map_pairs(opts.map_path)

# ---------- output / execution ----------

def sorted_rows_from_map(mapping):
    return [(inp, out) for out, inp in sorted(mapping.items(), key=lambda kv: kv[0])]

def print_table(rows):
    if not rows:
        return
    w1 = max([len('Input')] + [len(r[0]) for r in rows])
    w2 = max([len('Output')] + [len(r[1]) for r in rows])
    border = '+' + '-' * (w1 + 2) + '+' + '-' * (w2 + 2) + '+'
    print(border)
    print('| ' + 'Input'.ljust(w1) + ' | ' + 'Output'.ljust(w2) + ' |')
    print(border)
    for inp, out in rows:
        print('| ' + inp.ljust(w1) + ' | ' + out.ljust(w2) + ' |')
    print(border)

def write_generate(path, mapping):
    # mapping is output -> input, already final. Sort lexicographically by output.
    ordered = OrderedDict((k, mapping[k]) for k in sorted(mapping.keys()))
    try:
        with open(path, 'w', encoding='utf-8') as f:
            if not ordered:
                f.write('{}')
            else:
                f.write(json.dumps(ordered, ensure_ascii=False, indent=2))
    except OSError as e:
        raise AppError('error: ' + os_error_text(e), 1)

def execute_candidates(opts, candidates):
    # Returns (output_to_input map, had_errors)
    output_to_input = OrderedDict()
    had_errors = False
    if opts.test:
        initial = build_initial_set()
        for inp, desired in candidates:
            final = resolve_collision_initial(desired, inp, initial, opts.overwrite)
            output_to_input[final] = inp
        return output_to_input, False

    for inp, desired in candidates:
        final = resolve_collision_current(desired, inp, opts.overwrite)
        try:
            if opts.mkdir:
                parent = os.path.dirname(final)
                if parent:
                    os.makedirs(parent, exist_ok=True)
            os.rename(inp, final)
            output_to_input[final] = inp
        except OSError as e:
            had_errors = True
            eprint(f"[error] unable to rename '{inp}': {os_error_text(e)}")
    return output_to_input, had_errors

# ---------- main ----------

def regex_required_usage(argv0, opts):
    name = prog_base(argv0)
    # Clap builds a contextual usage. This approximation matches the common/simple case.
    parts = [name]
    if opts.test:
        parts.append('--test')
    if opts.dir != '.':
        parts.append('--dir <PATH>')
    if opts.map_path is not None:
        parts.append('--map <PATH>')
    parts.append('--regex <PATTERN>')
    parts.append('<[SOURCE] OUTPUT>...')
    return 'Usage: ' + ' '.join(parts)

def run(argv):
    opts = parse_args(argv)
    argv0 = argv[0]

    # Clap-enforced required positional for --regex occurs before running application logic/chdir.
    if opts.regex is not None and len(opts.positionals) == 0:
        msg = ("error: the following required arguments were not provided:\n"
               "  <[SOURCE] OUTPUT>...\n\n"
               f"{regex_required_usage(argv0, opts)}\n\n"
               "For more information, try '--help'.")
        raise AppError(msg, 2)

    # Application changes working directory early; many custom validation errors happen after this.
    try:
        os.chdir(opts.dir)
    except OSError as e:
        raise AppError('error: ' + os_error_text(e), 1)

    has_flag_mode = opts.regex is not None or opts.sort is not None or opts.map_path is not None
    if has_flag_mode and len(opts.positionals) > 1:
        raise AppError("error: optional SOURCE must be used without setting regex, map or sort flags", 1)

    # Mode precedence observed: regex > sort > map > positional SOURCE/OUTPUT.
    mode = None
    source_pattern = None
    output_pattern = None
    if opts.regex is not None:
        mode = 'regex'
        source_pattern = opts.regex
        output_pattern = opts.positionals[0]
    elif opts.sort is not None:
        mode = 'sort'
        if len(opts.positionals) == 0:
            raise AppError("error: [output-format] output formatter must be set", 1)
        output_pattern = opts.positionals[0]
    elif opts.map_path is not None:
        mode = 'map'
    else:
        if len(opts.positionals) < 2:
            raise AppError(f"error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '{argv0} --help' for more information.", 1)
        mode = 'regex'
        source_pattern = opts.positionals[-2]
        opts.regex = source_pattern
        output_pattern = opts.positionals[-1]

    candidates = []
    if mode == 'sort':
        formatter = Formatter(output_pattern)
        candidates = candidate_sort(opts, formatter)
    elif mode == 'regex':
        formatter = Formatter(output_pattern)
        cre = compile_regex(source_pattern)
        candidates = candidate_regex(opts, formatter, cre)
    elif mode == 'map':
        candidates = candidate_map(opts)

    mapping, had_errors = execute_candidates(opts, candidates)

    if opts.generate is not None:
        write_generate(opts.generate, mapping)

    if not opts.quiet:
        print_table(sorted_rows_from_map(mapping))

    return 1 if had_errors else 0

def main():
    try:
        code = run(sys.argv)
    except CliExit as e:
        code = e.code
    except AppError as e:
        eprint(e.msg)
        code = e.code
    sys.exit(code)

if __name__ == '__main__':
    main()
