def eprint(s=""):
    print(s, file=sys.stderr)

def os_error_text(exc):
    if isinstance(exc, OSError):
        msg = exc.strerror or str(exc)
        num = exc.errno
        if num is not None:
            return f"{msg} (os error {num})"
    return str(exc)

# ---------- CLI parsing ----------

def usage_general(name):
    return f"Usage: {name} [OPTIONS] [[SOURCE] OUTPUT]..."

def unexpected_arg(arg, name):
    return (f"error: unexpected argument '{arg}' found\n\n"
            f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"
            f"{usage_general(name)}\n\n"
            f"For more information, try '--help'.")

def missing_value(opt, value_name, possible=False):
    s = f"error: a value is required for '{opt} <{value_name}>' but none was supplied"
    if possible:
        s += "\n  [possible values: asc, desc]"
    s += "\n\nFor more information, try '--help'."
    return s

def invalid_sort(val):
    return (f"error: invalid value '{val}' for '--sort <ORDER>'\n"
            f"  [possible values: asc, desc]\n\n"
            f"For more information, try '--help'.")

def invalid_uint(val, opt):
    return (f"error: invalid value '{val}' for '{opt} <DEPTH>': invalid digit found in string\n\n"
            f"For more information, try '--help'.")

def parse_uint_value(val, optname):
    if val == "" or not val.isdigit():
        raise AppError(invalid_uint(val, optname), 2)
    try:
        return int(val)
    except Exception:
        raise AppError(invalid_uint(val, optname), 2)

def parse_args(argv):
    name = prog_base(argv[0])
    opts = Options()
    args = argv[1:]
    i = 0
    end_opts = False

    def need_next(current, value_name, possible=False):
        nonlocal i
        if i + 1 >= len(args):
            raise AppError(missing_value(current, value_name, possible), 2)
        nxt = args[i+1]
        if nxt.startswith('-'):
            # clap reports negative-looking values as unexpected arguments unless passed with '='
            raise AppError(unexpected_arg(nxt, name), 2)
        i += 1
        return nxt

    long_value_names = {
        'dir': ('PATH', False), 'depth': ('DEPTH', False), 'generate': ('PATH', False),
        'map': ('PATH', False), 'from-file': ('PATH', False), 'max-depth': ('DEPTH', False),
        'regex': ('PATTERN', False), 'sort': ('ORDER', True)
    }

    while i < len(args):
        a = args[i]
        if end_opts:
            opts.positionals.append(a)
            i += 1
            continue
        if a == '--':
            end_opts = True
            i += 1
            continue
        if a == '--help':
            sys.stdout.write(long_help(name))
            raise CliExit(0)
        if a == '--version':
            print(VERSION)
            raise CliExit(0)
        if a.startswith('--') and len(a) > 2:
            body = a[2:]
            if '=' in body:
                key, val = body.split('=', 1)
                has_eq = True
            else:
                key, val = body, None
                has_eq = False
            if key == 'no-extension':
                opts.no_extension = True
            elif key == 'help':
                sys.stdout.write(long_help(name)); raise CliExit(0)
            elif key == 'mkdir':
                opts.mkdir = True
            elif key == 'quiet':
                opts.quiet = True
            elif key in ('test', 'dry-run'):
                opts.test = True
            elif key == 'version':
                print(VERSION); raise CliExit(0)
            elif key == 'overwrite':
                opts.overwrite = True
            elif key in long_value_names:
                vname, poss = long_value_names[key]
                opt_display = '--from-file' if key == 'from-file' else '--' + key
                if has_eq:
                    if val == "":
                        raise AppError(missing_value(opt_display, vname, poss), 2)
                    value = val
                else:
                    value = need_next(opt_display, vname, poss)
                if key == 'dir':
                    opts.dir = value
                elif key == 'depth':
